# ==============================================================================
# Build the 48-subplot environmental / ecosystem-function / TPL tables
# ==============================================================================
# External inputs are read only from ./data. TPL beta estimates are generated by
# the earlier empirical scripts under ./results.
#
# The manuscript states that 11-year means and temporal coefficients of
# variation (CV = SD / mean) were calculated at the subplot level. This script
# performs that aggregation and merges the resulting variables with beta_t and
# beta_p for use by the piecewise SEM and ecosystem-function analyses.
# ==============================================================================

rm(list = ls())
PROJECT_DIR <- normalizePath(Sys.getenv("TPL_PROJECT_ROOT", unset = getwd()), mustWork = TRUE)
setwd(PROJECT_DIR)

ENV_FILE <- "./data/summary of environmental data2010-2020.csv"
META_FILE <- "./data/prepared/treatment_metadata_48plots.csv"
TTTPL_FILE <- "./results/01_tTTPL/UPARSE_all_groups_plot_level_revision_metrics.csv"
PTTPL_FILE <- "./results/04_pTTPL/pTTPL_all_groups_plot_level_full_precision.csv"
TTTPL_SUBGROUP_FILE <- "./results/07_tTTPL_subgroup/tTTPL_phylum_trophic_plot_level_full_precision.rds"
PTTPL_SUBGROUP_FILE <- "./results/08_pTTPL_subgroup/pTTPL_phylum_trophic_plot_level_full_precision.rds"
OUT_DIR <- "./results/10_environment_SEM_inputs"
dir.create(OUT_DIR, recursive = TRUE, showWarnings = FALSE)

for (f in c(ENV_FILE, META_FILE, TTTPL_FILE, PTTPL_FILE)) {
  if (!file.exists(f)) stop("Required input not found: ", f)
}

env <- read.csv(ENV_FILE, check.names = FALSE, stringsAsFactors = FALSE)
names(env)[1] <- "Sample_name"
env$plot <- as.character(env$plot)
env$year <- as.numeric(env$year)
env <- env[env$year %in% 2010:2020, , drop = FALSE]

cv <- function(x) {
  x <- as.numeric(x)
  x <- x[is.finite(x)]
  if (length(x) < 2L) return(NA_real_)
  mu <- mean(x)
  if (!is.finite(mu) || mu == 0) return(NA_real_)
  stats::sd(x) / mu
}
mean_safe <- function(x) {
  x <- as.numeric(x)
  x <- x[is.finite(x)]
  if (!length(x)) NA_real_ else mean(x)
}

# Explicit source-column mapping. Keeping this mapping here makes the derivation
# of manuscript variable names auditable from the raw environmental table.
source_map <- c(
  temperature = "temperature_annual",
  moisture = "annual_moisture",
  pH = "pH",
  NO3N = "NO3-N",
  TC = "TC",
  plant_biomass = "FlTotl",
  plant_richness = "plant richness",
  ER = "ER_annualmean",
  GPP = "GPP_annualmean",
  NEE = "NEE_annualmean",
  Ra = "Autotrophic",
  Rh = "Heterotrophic",
  Rs = "total_soil_respiration"
)
missing_cols <- setdiff(unname(source_map), names(env))
if (length(missing_cols)) stop("Environmental table is missing: ", paste(missing_cols, collapse = ", "))

plots <- unique(env$plot)
plot_env <- do.call(rbind, lapply(plots, function(p) {
  d <- env[env$plot == p, , drop = FALSE]
  data.frame(
    plot = p,
    temperature_mean = mean_safe(d[[source_map["temperature"]]]),
    temperature_cv = cv(d[[source_map["temperature"]]]),
    moisture_mean = mean_safe(d[[source_map["moisture"]]]),
    moisture_cv = cv(d[[source_map["moisture"]]]),
    pH_mean = mean_safe(d[[source_map["pH"]]]),
    pH_cv = cv(d[[source_map["pH"]]]),
    NO3N_mean = mean_safe(d[[source_map["NO3N"]]]),
    NO3N_cv = cv(d[[source_map["NO3N"]]]),
    TC_mean = mean_safe(d[[source_map["TC"]]]),
    TC_cv = cv(d[[source_map["TC"]]]),
    plant_biomass_mean = mean_safe(d[[source_map["plant_biomass"]]]),
    plant_biomass_cv = cv(d[[source_map["plant_biomass"]]]),
    plant_richness_mean = mean_safe(d[[source_map["plant_richness"]]]),
    plant_richness_cv = cv(d[[source_map["plant_richness"]]]),
    ER_mean = mean_safe(d[[source_map["ER"]]]),
    ER_cv = cv(d[[source_map["ER"]]]),
    GPP_mean = mean_safe(d[[source_map["GPP"]]]),
    GPP_cv = cv(d[[source_map["GPP"]]]),
    NEE_mean = mean_safe(d[[source_map["NEE"]]]),
    NEE_cv = cv(d[[source_map["NEE"]]]),
    Ra_mean = mean_safe(d[[source_map["Ra"]]]),
    Ra_cv = cv(d[[source_map["Ra"]]]),
    Rh_mean = mean_safe(d[[source_map["Rh"]]]),
    Rh_cv = cv(d[[source_map["Rh"]]]),
    Rs_mean = mean_safe(d[[source_map["Rs"]]]),
    Rs_cv = cv(d[[source_map["Rs"]]]),
    stringsAsFactors = FALSE
  )
}))

# Merge whole-community beta values to a 48-row wide table.
group_to_t <- c(
  Bacteria = "Bac_beta", Archaea = "Arch_beta", Fungi = "Fun_18S_beta",
  Protists = "Pro_beta", Nematoda = "Nem_beta"
)
group_to_p <- c(
  Bacteria = "Bac_pTTPL_beta", Archaea = "Arch_pTTPL_beta", Fungi = "Fun_18S_pTTPL_beta",
  Protists = "Pro_pTTPL_beta", Nematoda = "Nem_pTTPL_beta"
)

wide_beta <- function(file, mapping) {
  x <- read.csv(file, check.names = FALSE, stringsAsFactors = FALSE)
  plot_col <- if ("Plot" %in% names(x)) "Plot" else if ("plot" %in% names(x)) "plot" else stop("No Plot column in ", file)
  if (!all(c("Group", "Beta_raw") %in% names(x))) stop("Missing Group/Beta_raw in ", file)
  out <- data.frame(plot = unique(as.character(x[[plot_col]])), stringsAsFactors = FALSE)
  for (g in names(mapping)) {
    d <- x[x$Group == g, c(plot_col, "Beta_raw"), drop = FALSE]
    names(d) <- c("plot", mapping[[g]])
    out <- merge(out, d, by = "plot", all = TRUE, sort = FALSE)
  }
  out
}

t_beta <- wide_beta(TTTPL_FILE, group_to_t)
p_beta <- wide_beta(PTTPL_FILE, group_to_p)

all48 <- Reduce(function(a, b) merge(a, b, by = "plot", all = TRUE, sort = FALSE),
                list(plot_env, t_beta, p_beta))
meta <- read.csv(META_FILE, check.names = FALSE, stringsAsFactors = FALSE)
all48 <- merge(meta, all48, by = "plot", all.x = TRUE, sort = FALSE)

# Preserve the 48-row treatment-file order.
all48 <- all48[match(meta$plot, all48$plot), , drop = FALSE]
if (nrow(all48) != 48L || anyDuplicated(all48$plot)) stop("Expected exactly 48 unique subplot rows.")

write_with_plot_rownames <- function(x, file) {
  y <- x
  rownames(y) <- y$plot
  y$plot <- NULL
  write.csv(y, file, quote = FALSE)
}

write_with_plot_rownames(all48, file.path(OUT_DIR, "all_environment_TPL_function_48plots.csv"))
write_with_plot_rownames(all48, file.path(OUT_DIR, "tTTPL_SEM_input.csv"))
write_with_plot_rownames(all48, file.path(OUT_DIR, "pTTPL_SEM_input.csv"))
write.csv(meta, file.path(OUT_DIR, "treatment_metadata_48plots.csv"), row.names = FALSE, quote = FALSE)
write.csv(data.frame(Manuscript_variable = c(
  "temperature", "moisture", "pH", "NO3N", "TC", "plant_biomass", "plant_richness",
  "ER", "GPP", "NEE", "Ra", "Rh", "Rs"
), Source_column = unname(source_map)),
file.path(OUT_DIR, "environment_variable_mapping.csv"), row.names = FALSE, quote = FALSE)

# Optional wide subgroup beta tables for the ecosystem-function analysis.
wide_subgroup <- function(rds_file, prefix, out_file) {
  if (!file.exists(rds_file)) return(invisible(NULL))
  x <- readRDS(rds_file)
  needed <- c("Group", "Level_type", "Subgroup", "Plot", "Beta_raw")
  if (!all(needed %in% names(x))) stop("Subgroup RDS missing required columns: ", rds_file)
  x$key <- paste(x$Group, x$Level_type, x$Subgroup, prefix, sep = "__")
  keys <- unique(x$key)
  out <- data.frame(plot = meta$plot, stringsAsFactors = FALSE)
  for (k in keys) {
    d <- x[x$key == k, c("Plot", "Beta_raw"), drop = FALSE]
    names(d) <- c("plot", k)
    out <- merge(out, d, by = "plot", all.x = TRUE, sort = FALSE)
  }
  out <- out[match(meta$plot, out$plot), , drop = FALSE]
  rownames(out) <- out$plot
  out$plot <- NULL
  write.csv(out, out_file, quote = FALSE)
}

wide_subgroup(TTTPL_SUBGROUP_FILE, "tTTPL",
              file.path(OUT_DIR, "tTTPL_subgroup_beta_wide.csv"))
wide_subgroup(PTTPL_SUBGROUP_FILE, "pTTPL",
              file.path(OUT_DIR, "pTTPL_subgroup_beta_wide.csv"))

message("Prepared 48-subplot environmental/TPL tables in: ", OUT_DIR)
